def C_N_S(S, N):
    if N > S:
        return 0
    S_prime = S - 2 * (N - 1)
    if S_prime < 0:
        return 0
    # Formula for number of points in a hexagon of side S'
    return 3 * S_prime**2 - 3 * S_prime + 1

S = 100
N_values = [1, 2, 3, 4]
results = {}
for N in N_values:
    results[N] = C_N_S(S, N)

print(results)
